rows.cypher:
MATCH (e:Entity)<-[:REFERENCES|MODIFIES]-(c:Circular) RETURN e.name AS document, e.type AS type, e.number AS number, count(DISTINCT c) AS citations ORDER BY citations DESC
;
MATCH (c:Circular)-[:CONTAINS]->(:Clause)-[r:REFERENCES|MODIFIES]->(e:Entity) RETURN e.name AS document, e.type AS type, e.number AS number, count(DISTINCT c) AS citations ORDER BY citations DESC
